namespace NovaHarvest.Core.Dialogue;public sealed class DialogueNode {readonly List<DialogueChoice> _choices=new();public string Id{get;}public string Speaker{get;}public string Text{get;}public IReadOnlyList<DialogueChoice> Choices=>_choices;public string? NextNodeId{get;private set;}public bool IsEnd=>string.IsNullOrWhiteSpace(NextNodeId)&&_choices.Count==0;public DialogueNode(string id,string speaker,string text){Id=id;Speaker=speaker;Text=text;}public void SetNextNode(string id)=>NextNodeId=id;public void AddChoice(DialogueChoice c)=>_choices.Add(c);}
